from lesson_authoring import entry as E
from author_batch200_root_post_a import B
W=[
E('postdoctoral','英 /ˌpəʊstˈdɒktərəl/；美 /ˌpoʊstˈdɑktərəl/','博士后的','博士学位已经取得，再往后进入一段进一步研究和训练的阶段。','post- 之后 + doctoral 博士的；doctoral 上接 doctor 及学位用法，不是说医生下班以后。',B+[['英语 post- + doctoral → postdoctoral','获得博士学位后的研究或训练相关']],'a postdoctoral researcher 是博士后研究人员；a postdoctoral fellowship 是相应研究职位或资助。它通常不是比博士更高一级的另一个学位，而是取得博士后的研究阶段。','postdoctoral research；a postdoctoral researcher；a postdoctoral fellowship。','doctoral 是博士阶段的，postdoctoral 是取得博士后的。postgraduate 范围较广，通常包括本科毕业后的硕士、博士等学习。',('She began a postdoctoral fellowship in molecular biology.','她开始了一项分子生物学博士后研究工作。'),('The laboratory is recruiting two postdoctoral researchers.','实验室正在招聘两名博士后研究人员。'),sources=['https://en.wiktionary.org/wiki/postdoctoral','https://www.merriam-webster.com/dictionary/postdoctoral']),
E('postdoc','英 /ˈpəʊstdɒk/；美 /ˈpoʊstdɑk/','博士后研究人员；博士后职位或阶段','学术圈把长长的 postdoctoral 缩短，聊天时直接说 postdoc。','postdoctoral 的缩略形式；可进一步指相应的人、岗位或研究经历，具体看句子。',B+[['post- + doctoral → postdoctoral','博士后的'],['postdoctoral → postdoc','缩略为研究阶段、岗位或人员名称']],'She is a postdoc 说她是博士后研究人员；do a postdoc 说从事一段博士后研究；a postdoc position 是博士后职位。它不是普通学生对老师的称呼。','do a postdoc；a postdoc position；a postdoc in a laboratory。','postdoc 是日常学术交流中的缩写，正式职位名称常用 postdoctoral researcher 或 fellow；不同机构的具体称谓可能不同。',('He is a postdoc in the astronomy department.','他是天文学系的一名博士后研究人员。'),('She did a postdoc abroad before joining the university.','加入这所大学前，她在国外做过博士后研究。'),sources=['https://en.wiktionary.org/wiki/postdoc','https://www.oxfordlearnersdictionaries.com/definition/english/postdoc']),
E('postsecondary','英 /ˌpəʊstˈsekəndəri/；美 /ˌpoʊstˈsekənderi/','中学后的；中等教育之后的','高中或其他中等教育阶段结束，接着走向大学、专科或其他后续教育。','post- 之后 + secondary 中等教育的；不是“第二次之后”，这里 secondary 属于教育阶段名称。',B+[['英语 post- + secondary → postsecondary','中等教育完成之后的']],'postsecondary education 包括中等教育以后的多种教育形式；postsecondary institutions 可包括大学、学院和部分职业教育机构，范围依具体教育体系而定。','postsecondary education；postsecondary institutions；postsecondary training。','postsecondary 不等于 postgraduate。前者以中等教育为分界，后者通常以本科毕业为分界。',('The scholarship helps students enter postsecondary education.','这项奖学金帮助学生接受中学后的教育。'),('The survey includes universities and other postsecondary institutions.','调查涵盖大学和其他中等教育之后的教育机构。'),sources=['https://www.merriam-webster.com/dictionary/postsecondary','https://en.wiktionary.org/wiki/postsecondary']),
E('postoperative','英 /ˌpəʊstˈɒpərətɪv/；美 /ˌpoʊstˈɑpərətɪv/','手术后的；术后的','手术完成是一道时间线，接下来的观察、护理和恢复都在这条线后面。','post- 之后 + operative 与手术相关的；operative 在这里接 operation 的外科手术义。',B+[['英语 post- + operative → postoperative','发生或安排在手术之后的']],'postoperative care 是术后护理；a postoperative appointment 是术后复诊。单词只给出与手术的时间关系，不说明手术类型，也不自动意味着有并发症。','postoperative care；postoperative recovery；a postoperative appointment。','preoperative 是术前，postoperative 是术后。operative 在此不是泛指“工作有效”，而是手术相关。',('The nurse explained the postoperative care plan.','护士解释了术后护理计划。'),('A postoperative appointment was arranged before she left the hospital.','她离院前已经安排好了术后复诊。'),sources=['https://en.wiktionary.org/wiki/postoperative','https://www.merriam-webster.com/dictionary/postoperative']),
E('postpartum','英 /ˌpəʊstˈpɑːtəm/；美 /ˌpoʊstˈpɑrtəm/','产后的；分娩之后','以分娩为时间点，描述母亲接下来的身体、照护或生活阶段。','来自拉丁短语 post partum，post 之后 + partum 分娩，是 partus 的格变化；不是英语 part 部分加尾巴。',B+[['拉丁 post partum','分娩以后'],['英语 postpartum','产后的；在产后']],'postpartum care 是产后护理；three weeks postpartum 是分娩后三周。postpartum depression 是产后抑郁这一完整词组，但 postpartum 单独并不等于抑郁。','postpartum care；the postpartum period；three weeks postpartum。','postnatal 常说出生后的，范围可涉及母婴；postpartum 更直接以分娩及产妇为中心。两者在部分场合重叠。',('The clinic provides postpartum care and family support.','这家诊所提供产后护理和家庭支持。'),('The interview took place six weeks postpartum.','访谈在分娩后六周进行。'),sources=['https://www.merriam-webster.com/dictionary/postpartum','https://en.wiktionary.org/wiki/postpartum']),
E('posttraumatic','英 /ˌpəʊsttrɔːˈmætɪk/；美 /ˌpoʊsttrəˈmætɪk/','创伤后的；创伤所致的','受伤或经历创伤性事件之后，描述接下来出现的相关状态。','post- 之后 + traumatic 创伤相关的；traumatic 接希腊 trauma 伤。可涉及身体或心理创伤。',B+[['post- + traumatic → posttraumatic','创伤以后发生的，或由创伤引起的']],'posttraumatic symptoms 是创伤后的症状；posttraumatic stress disorder 是创伤后应激障碍，缩写 PTSD。posttraumatic 只是形容词，不能把任何创伤后的反应都直接等同于完整的疾病名称。','posttraumatic symptoms；posttraumatic stress；posttraumatic recovery。','traumatic 描述创伤性或与创伤有关，posttraumatic 多了之后发生这一关系。PTSD 中的 disorder 不能在翻译时凭空省掉。',('The article discusses posttraumatic symptoms after serious accidents.','文章讨论了严重事故后的创伤相关症状。'),('Her research focuses on posttraumatic recovery.','她的研究关注创伤后的恢复。'),sources=['https://www.merriam-webster.com/dictionary/posttraumatic','https://en.wiktionary.org/wiki/posttraumatic']),
E('postgame','英 /ˈpəʊstɡeɪm/；美 /ˈpoʊstɡeɪm/','赛后的','终场哨已经响了，球员采访、教练总结和电视点评随后开始。','post- 之后 + game 比赛；英语合成，常放在名词前。',B+[['英语 post- + game → postgame','比赛之后的']],'a postgame interview 是赛后采访；postgame analysis 是赛后分析。它表示单场比赛之后，不是整个赛季结束后的阶段。','a postgame interview；postgame analysis；a postgame press conference。','postgame 对应一场 game 之后；postseason 指常规赛之后的赛事阶段，例如季后赛，时间范围不同。',('The coach answered questions at the postgame press conference.','教练在赛后新闻发布会上回答了问题。'),('The channel devoted an hour to postgame analysis.','频道用一个小时进行了赛后分析。'),sources=['https://en.wiktionary.org/wiki/postgame','https://www.merriam-webster.com/dictionary/postgame']),
E('postmodernism','英 /ˌpəʊstˈmɒdənɪzəm/；美 /ˌpoʊstˈmɑdərnɪzəm/','后现代主义','可以先想象作品把不同年代、不同风格拼在一起，连“必须只有一种正确讲法”也拿来追问。','post- 之后 + modernism 现代主义；是现代文化与思想语境中的名称，不能只当作“现在之后”。',B+[['英语 post- + modernism → postmodernism','对现代主义及现代思想某些主张的后续回应']],'在艺术、文学、建筑与哲学中，postmodernism 的范围不完全相同。拼贴、戏仿、混用风格可帮助理解部分艺术作品；思想讨论则常涉及对统一解释和确定性的质疑。这是一组相关倾向，不是一个简单口号。','postmodernism in literature；debates about postmodernism；modernism and postmodernism。','postmodernism 不表示所有今天的新作品，也不等于作者只是在胡说。具体含义要看讨论的领域与理论背景。',('The course explores postmodernism in literature and architecture.','这门课探讨文学与建筑中的后现代主义。'),('The essay compares different interpretations of postmodernism.','这篇文章比较了对后现代主义的不同理解。'),sources=['https://www.etymonline.com/word/postmodernism','https://plato.stanford.edu/entries/postmodernism/','https://en.wiktionary.org/wiki/postmodernism'])
]
